364	  // An empty agent is refused here rather than sent to GitHub, which rejects it with
365	  // `HTTP 422: Required input 'agent' not provided`. The doc comment on
366	  // `aggregation.ts`'s `parentAgent` has claimed this refusal for a while; it was not
367	  // there, and the 422 was the only thing that stopped a run for an agent called "".
368	  //
369	  // The caller that reaches this is the aggregation gate, when the parent's thread
370	  // names no agent -- see `mostRecentAgent`. `failed` is the honest answer: nothing is
371	  // running and nothing will retry, which is what the gate reports as
372	  // `dispatch-failed`.
373	  if (!d.agent.trim()) {
374	    const log = d.log ?? ((message: string) => console.error(message));
375	    log(`${d.context}: no agent was named, so nothing was dispatched (an empty agent is not a run).`);
376	    return "failed";
377	  }
378	
379	  const state = readTargetState(d.number, d.repo);
380	  if (!mayStartWorkOn(state)) return refuseClosedTarget(d, state);
381	
382	  // The marker goes out before the check, so the check has something to be ordered
383	  // against. A dispatch that answers a request skips both: the request it would find
384	  // is its own, and the marker would be a second one for one turn.
385	  if (!d.answersRequest) {
386	    const markerId = postDispatchMarker(d);
387	    const refusal = refuseOutstandingRequest(d, markerId);
388	    if (refusal !== undefined) return refusal;
389	  }
390	
391	  const args = [
392	    ...(d.repo ? ["--repo", d.repo] : []),
393	    "--field", `agent=${d.agent}`,
394	    "--field", `number=${d.number}`,
395	    "--field", `type=${d.type}`,
396	    "--field", `notify=${d.notify ?? ""}`,
397	    // Always sent, so the input has a value on every path rather than defaulting in
398	    // one place and being absent in another.
399	    "--field", `reload_count=${d.reloadCount ?? 0}`,
400	    // Empty when a person or the machinery started the run -- see `dispatchedBy`.
401	    "--field", `dispatched_by=${d.dispatchedBy ?? ""}`,
402	  ];
403	  if (!dispatchWorkflow(d.context, runnerWorkflow(), args, d.log)) return "failed";
404	  // The default classification compares the target with this run's own node
405	  // (`run-node.ts`): onto it moves the turn on, under it starts work and leaves this
406	  // node waiting. `continuesChain` overrides it for the dispatch that is the run's
407	  // own conclusion landing on another node — neither on it nor under it — whose
408	  // caller passes the fact the comparison cannot recover. See `RunnerDispatch` and
