    if (d.freshnessProbeId === undefined || read.probeVisible) break;
    const delay = delays[attempt];
    if (delay === undefined) break;
    log(`${d.context}: the comment this dispatch was to answer with on #${d.number} is not visible yet; waiting ${delay}ms and reading again`);
    Bun.sleepSync(delay);
