  if (read === undefined || (d.freshnessProbeId !== undefined && !read.probeVisible)) {
    log(
      `${d.context}: the thread on #${d.number} could not be confirmed current, so whether it still waits for ` +
        `${d.agent} could not be established and nothing was started`,
